def transform_rules_n3(input_grid):
    """Transform 3x3 input to 5x5 output based on observed corner/edge/center rules"""
    n = len(input_grid)
    output_size = 2 * n - 1
    output = [[0] * output_size for _ in range(output_size)]

    # Four corners expand to 2x2 output blocks
    # Input(0,0) -> output[0:2, 0:2]
    for i_out in range(2):
        for j_out in range(2):
            output[i_out][j_out] = input_grid[0][0]

    # Input(0,n-1) -> output[0:2, n:2n-1]
    for i_out in range(2):
        for j_out in range(n, output_size):
            output[i_out][j_out] = input_grid[0][n-1]

    # Input(n-1,0) -> output[n:2n-1, 0:2] wait no, output[n:2n-1, 0:2]
    for i_out in range(n, output_size):
        for j_out in range(2):
            output[i_out][j_out] = input_grid[n-1][0]

    # Input(n-1,n-1) -> output[n:2n-1, n:2n-1]
    for i_out in range(n, output_size):
        for j_out in range(n, output_size):
            output[i_out][j_out] = input_grid[n-1][n-1]

    # Four edge cells expand to 1x2 or 2x1 blocks
    # Input(0,1) -> output[0:2, n-1:n]
    for i_out in range(2):
        output[i_out][n-1] = input_grid[0][1]

    # Input(1,0) -> output[n-1, 0:n-1+1]? output[n, 0:2]
    for j_out in range(2):
        output[n, j_out] = input_grid[1][0]

    # Input(1,n-1) -> output[n, n:2n-1]
    for j_out in range(n, output_size):
        output[n, j_out] = input_grid[1][n-1]

    # Input(n-1,1) -> output[n+1:2n-1, n-1:n]
    for i_out in range(n + 1, output_size):
        output[i_out][n-1] = input_grid[n-1][1]

    # Center cell (1,1) -> output[n-1: n, n-1:n] -> just output[n-1, n-1]
    output[n-1][n-1] = input_grid[1][1]  # Wait n=3, n-1=2. output[2,2]

    # Hmm but the demo shows output(2,2)=1 which comes from input(1,1)=1. That matches!

    return output

