def transform_fixed(input_grid):
    n = len(input_grid)
    output_size = 2 * n - 1
    output = [[0] * output_size for _ in range(output_size)]

    # Four corners expand to 2x2 output blocks
    for i_out in range(2):
        for j_out in range(2):
            output[i_out][j_out] = input_grid[0][0]

    for i_out in range(2):
        for j_out in range(n, output_size):
            output[i_out][j_out] = input_grid[0][n-1]

    for i_out in range(n-1, output_size):
        for j_out in range(2):
            output[i_out][j_out] = input_grid[n-1][0]

    for i_out in range(n-1, output_size):
        for j_out in range(n, output_size):
            output[i_out][j_out] = input_grid[n-1][n-1]

    # Edge cells at ROW n-1
    for i_out in range(2):
        output[i_out][n-1] = input_grid[0][1]

    for j_out in range(2):
        output[n-1][j_out] = input_grid[1][0]

    for j_out in range(n, output_size):
        output[n-1][j_out] = input_grid[1][n-1]

    for i_out in range(n-1, output_size):
        output[i_out][n-1] = input_grid[n-1][1]

    # Center cell
    output[n-1][n-1] = input_grid[1][1]

    return output

